import{_ as p,a0 as o,w as r,s as d,ao as l,I as i,x as e,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Telnet，愛一直在 | LCTT x X-CMD","titleTemplate":false,"description":"Telnet，愛一直在 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Telnet，愛一直在 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Telnet，愛一直在 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171231 Why You Should Still Love Telnet","title":"Telnet，愛一直在","tag":"201802","desc":""},"relativePath":"201802/20171231 Why You Should Still Love Telnet.md","filePath":"[post].md"}'),c={name:"201802/20171231 Why You Should Still Love Telnet.md"};function h(g,s,b,m,k,u){const a=o("Link");return r(),d("div",null,[s[21]||(s[21]=l('<h1 id="telnet-愛一直在" tabindex="-1">Telnet，愛一直在 <a class="header-anchor" href="#telnet-愛一直在" aria-label="Permalink to “Telnet，愛一直在”">​</a></h1><p>Telnet，是系統管理員登錄遠程服務器的一種協議和工具。然而，由於所有的通信都沒有加密，包括密碼，都是明文發送的。Telnet 在 SSH 被開發出來之後就基本棄用了。</p><p>登錄遠程服務器，你可能不會也從未考慮過它。但這並不意味着 <code>telnet</code> 命令在調試遠程連接問題時不是一個實用的工具。</p><p>本教程中，我們將探索使用 <code>telnet</code> 解決所有常見問題：“我怎麼又連不上啦？”</p><p>這種討厭的問題通常會在安裝了像 Web服務器、郵件服務器、ssh 服務器、Samba 服務器等諸如此類的事之後遇到，用户無法連接服務器。</p><p><code>telnet</code> 不會解決問題但可以很快縮小問題的範圍。</p><p><code>telnet</code> 用來調試網絡問題的簡單命令和語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet &lt;hostname or IP&gt; &lt;port&gt;</span></span></code></pre></div><p>因為 <code>telnet</code> 最初通過端口建立連接不會發送任何數據，適用於任何協議，包括加密協議。</p><p>連接問題服務器有四個可能會遇到的主要問題。我們會研究這四個問題，研究它們意味着什麼以及如何解決。</p>',10)),i("p",null,[s[1]||(s[1]=e("本教程默認已經在 ",-1)),s[2]||(s[2]=i("code",null,"samba.example.com",-1)),s[3]||(s[3]=e(" 安裝了 ",-1)),n(a,{href:"https://www.samba.org/"},{default:t(()=>[...s[0]||(s[0]=[e("Samba",-1)])]),_:1}),s[4]||(s[4]=e(" 服務器而且本地客户無法連上服務器。",-1))]),s[22]||(s[22]=l(`<h3 id="error-1-連接掛起" tabindex="-1">Error 1 - 連接掛起 <a class="header-anchor" href="#error-1-連接掛起" aria-label="Permalink to “Error 1 - 連接掛起”">​</a></h3><p>首先，我們需要試着用 <code>telnet</code> 連接 Samba 服務器。使用下列命令 (Samba 監聽端口445)：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span></code></pre></div><p>有時連接會莫名停止：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span>
<span class="line"><span>Trying 172.31.25.31...</span></span></code></pre></div><p>這意味着 <code>telnet</code> 沒有收到任何回應來建立連接。有兩個可能的原因：</p><ol><li>你和服務器之間有個路由器宕掉了。</li><li>防火牆攔截了你的請求。</li></ol>`,7)),i("p",null,[s[6]||(s[6]=e("為了排除第 1 點，對服務器上進行一個快速 ",-1)),n(a,{href:"https://www.systutorials.com/docs/linux/man/8-mtr/"},{default:t(()=>[...s[5]||(s[5]=[i("code",null,"mtr samba.example.com",-1)])]),_:1}),s[7]||(s[7]=e(" 。如果服務器是可達的，那麼便是防火牆（注意：防火牆總是存在的）。",-1))]),s[23]||(s[23]=l(`<p>首先用 <code>iptables -L -v -n</code> 命令檢查服務器本身有沒有防火牆，沒有的話你能看到以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -L -v -n</span></span>
<span class="line"><span>Chain INPUT (policy ACCEPT 0 packets, 0 bytes)</span></span>
<span class="line"><span> pkts bytes target prot opt in out source destination</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Chain FORWARD (policy ACCEPT 0 packets, 0 bytes)</span></span>
<span class="line"><span> pkts bytes target prot opt in out source destination</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Chain OUTPUT (policy ACCEPT 0 packets, 0 bytes)</span></span>
<span class="line"><span> pkts bytes target prot opt in out source destination</span></span></code></pre></div><p>如果你看到其他東西那可能就是問題所在了。為了檢驗，停止 <code>iptables</code> 一下並再次運行 <code>telnet samba.example.com 445</code> 看看你是否能連接。如果你還是不能連接看看你的提供商或企業有沒有防火牆攔截你。</p><h3 id="error-2-dns-問題" tabindex="-1">Error 2 - DNS 問題 <a class="header-anchor" href="#error-2-dns-問題" aria-label="Permalink to “Error 2 - DNS 問題”">​</a></h3><p>DNS 問題通常發生在你正使用的主機名沒有解析到 IP 地址。錯誤如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span>
<span class="line"><span>Server lookup failure: samba.example.com:445, Name or service not known</span></span></code></pre></div><p>第一步是把主機名替換成服務器的 IP 地址。如果你可以連上那麼就是主機名的問題。</p><p>有很多發生的原因（以下是我見過的）：</p><ol><li>域名註冊了嗎？用 <code>whois</code> 來檢驗。</li><li>域名過期了嗎？用 <code>whois</code> 來檢驗。</li><li>是否使用正確的主機名？用 <code>dig</code> 或 <code>host</code> 來確保你使用的主機名解析到正確的 IP。</li><li>你的 <strong>A</strong> 記錄正確嗎？確保你沒有偶然創建類似 <code>smaba.example.com</code> 的 <strong>A</strong> 記錄。</li></ol><p>一定要多檢查幾次拼寫和主機名是否正確（是 <code>samba.example.com</code> 還是 <code>samba1.example.com</code>）？這些經常會困擾你，特別是比較長、難記或其它國家的主機名。</p><h3 id="error-3-服務器沒有偵聽端口" tabindex="-1">Error 3 - 服務器沒有偵聽端口 <a class="header-anchor" href="#error-3-服務器沒有偵聽端口" aria-label="Permalink to “Error 3 - 服務器沒有偵聽端口”">​</a></h3><p>這種錯誤發生在 <code>telnet</code> 可達服務器但是指定端口沒有監聽。就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span>
<span class="line"><span>Trying 172.31.25.31...</span></span>
<span class="line"><span>telnet: Unable to connect to remote host: Connection refused</span></span></code></pre></div><p>有這些原因：</p><ol><li>你 <strong>確定</strong> 連接的是正確的服務器？</li><li>你的應用服務器沒有偵聽預期的端口。在服務器上運行 <code>netstat -plunt</code> 來查看它究竟在幹什麼並看哪個端口才是對的，實際正在監聽中的。</li><li>應用服務器沒有運行。這可能突然而又悄悄地發生在你啓動應用服務器之後。啓動服務器運行 <code>ps auxf</code> 或 <code>systemctl status application.service</code> 查看運行。</li></ol><h3 id="error-4-連接被服務器關閉" tabindex="-1">Error 4 - 連接被服務器關閉 <a class="header-anchor" href="#error-4-連接被服務器關閉" aria-label="Permalink to “Error 4 - 連接被服務器關閉”">​</a></h3><p>這種錯誤發生在連接成功建立但是應用服務器建立的安全措施一連上就將其結束。錯誤如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span>
<span class="line"><span>Trying 172.31.25.31...</span></span>
<span class="line"><span>Connected to samba.example.com.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span>
<span class="line"><span>Connection closed by foreign host.</span></span></code></pre></div><p>最後一行 <code>Connection closed by foreign host.</code> 意味着連接被服務器主動終止。為了修復這個問題，需要看看應用服務器的安全設置確保你的 IP 或用户允許連接。</p><h3 id="成功連接" tabindex="-1">成功連接 <a class="header-anchor" href="#成功連接" aria-label="Permalink to “成功連接”">​</a></h3><p>成功的 <code>telnet</code> 連接如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span>
<span class="line"><span>Trying 172.31.25.31...</span></span>
<span class="line"><span>Connected to samba.example.com.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span></code></pre></div><p>連接會保持一段時間只要你連接的應用服務器時限沒到。</p><p>輸入 <code>CTRL+]</code> 中止連接，然後當你看到 <code>telnet&gt;</code> 提示，輸入 <code>quit</code> 並按回車：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span>
<span class="line"><span>Trying 172.31.25.31...</span></span>
<span class="line"><span>Connected to samba.example.com.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span>
<span class="line"><span>^]</span></span>
<span class="line"><span>telnet&gt; quit</span></span>
<span class="line"><span>Connection closed.</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>客户程序連不上服務器的原因有很多。確切原因很難確定，特別是當客户是圖形用户界面提供很少或沒有錯誤信息。用 <code>telnet</code> 並觀察輸出可以讓你很快確定問題所在節約很多時間。</p><hr>`,28)),i("p",null,[s[9]||(s[9]=e("via: ",-1)),n(a,{href:"https://bash-prompt.net/guides/telnet/"},{default:t(()=>[...s[8]||(s[8]=[e("https://bash-prompt.net/guides/telnet/",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=e("作者：",-1)),n(a,{href:"https://bash-prompt.net"},{default:t(()=>[...s[10]||(s[10]=[e("Elliot Cooper",-1)])]),_:1}),s[14]||(s[14]=e(" 譯者：",-1)),n(a,{href:"https://github.com/XYenChi"},{default:t(()=>[...s[11]||(s[11]=[e("XYenChi",-1)])]),_:1}),s[15]||(s[15]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[16]||(s[16]=[e("LCTT",-1)])]),_:1}),s[19]||(s[19]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:t(()=>[...s[17]||(s[17]=[e("Linux中國",-1)])]),_:1}),s[20]||(s[20]=e(" 榮譽推出",-1))])])}const y=p(c,[["render",h]]);export{C as __pageData,y as default};
